+    fn handle_visual_selection_key(&mut self, key: UiKey) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.visual_selection = None;
+            }
+            UiKey::Char('v') => {
+                self.set_visual_selection_kind(VisualSelectionKind::Character);
+            }
+            UiKey::Char('V') => {
+                self.set_visual_selection_kind(VisualSelectionKind::Line);
+            }
+            UiKey::CtrlV => {
+                self.set_visual_selection_kind(VisualSelectionKind::Block);
+            }
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_selection(0, -1);
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_selection(1, 0);
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_selection(-1, 0);
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_selection(0, 1);
+            }
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn set_visual_selection_kind(&mut self, kind: VisualSelectionKind) {
+        if let Some(selection) = &mut self.visual_selection {
+            selection.kind = kind;
+            if kind == VisualSelectionKind::Line {
+                selection.anchor.column = 0;
+                selection.cursor.column = 0;
+            }
+        }
+    }
+
+    fn move_visual_selection(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(selection) = &mut self.visual_selection else {
+            return;
+        };
+        if selection.line_lengths.is_empty() {
+            return;
+        }
+
+        let max_row = selection.line_lengths.len().saturating_sub(1);
+        let next_row = offset_clamped(selection.cursor.row, row_delta, max_row);
+        let current_line_len = selection.line_lengths[selection.cursor.row];
+        let current_max_column = current_line_len.saturating_sub(1);
+        let mut next_column = if selection.kind == VisualSelectionKind::Line {
+            0
+        } else {
+            offset_clamped(selection.cursor.column, column_delta, current_max_column)
+        };
+        let next_line_len = selection.line_lengths[next_row];
+        next_column = next_column.min(next_line_len.saturating_sub(1));
+
+        selection.cursor = TextPosition {
+            row: next_row,
+            column: next_column,
+        };
+    }

