import os
import pty
import re
import select
import signal
import subprocess
import sys
import time

root = os.getcwd()
master, slave = pty.openpty()
env = os.environ.copy()
env.pop("WORK_LEAF_ORCHESTRATOR_URL", None)
proc = subprocess.Popen(
    [os.path.join(root, "target/debug/work-leaf")],
    stdin=slave,
    stdout=slave,
    stderr=slave,
    cwd=root,
    env=env,
    close_fds=True,
)
os.close(slave)
output = bytearray()

def read_for(seconds, needle=None):
    deadline = time.time() + seconds
    while time.time() < deadline:
        readable, _, _ = select.select([master], [], [], 0.1)
        if readable:
            try:
                chunk = os.read(master, 8192)
            except OSError:
                break
            if not chunk:
                break
            output.extend(chunk)
            if needle and needle in strip_ansi(output.decode(errors="replace")):
                return True
        if proc.poll() is not None:
            break
    return needle is None or needle in strip_ansi(output.decode(errors="replace"))

def send(data):
    os.write(master, data)

def strip_ansi(text):
    text = re.sub(r"\x1b\[[0-9;?]*[ -/]*[@-~]", "", text)
    return text.replace("\r", "\n")

try:
    if not read_for(20, "Command chat:"):
        raise RuntimeError("work-leaf did not render command chat")
    send(b":new Reply exactly READY_FOR_SLASH_COMMAND and do not modify files.\n")
    if not read_for(180, "READY_FOR_SLASH_COMMAND"):
        raise RuntimeError("real agent did not reach launch ready marker")
    send(b"\x1b/status\n")
    if not read_for(90, "user: /status"):
        raise RuntimeError("selected-agent /status was not appended")
    status_snapshot = strip_ansi(output.decode(errors="replace"))
    send(b"\x1b/fork\n")
    if not read_for(90, "user: /fork"):
        raise RuntimeError("selected-agent /fork was not appended")
    final = strip_ansi(output.decode(errors="replace"))
    for label, needle in [
        ("launch", "READY_FOR_SLASH_COMMAND"),
        ("status_user_line", "user: /status"),
        ("fork_user_line", "user: /fork"),
    ]:
        print(f"{label}: {needle in final}")
    tail_lines = [line for line in final.splitlines() if "READY_FOR_SLASH_COMMAND" in line or "/status" in line or "/fork" in line or "chat>" in line]
    print("visible_tail:")
    for line in tail_lines[-20:]:
        print(line[:200])
finally:
    try:
        send(b"\x1b:q\n")
        read_for(2)
    except Exception:
        pass
    if proc.poll() is None:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except subprocess.TimeoutExpired:
            proc.kill()
            proc.wait(timeout=5)
    os.close(master)
