+#[test]
+fn controller_yes_closes_reviewed_patch_chat_and_follow_up_reopens_it() {
+    let root = git_repo("workspace-review-done-confirmation");
+    fs::write(root.join("README.md"), "before\n").unwrap();
+    git(&root, ["add", "README.md"]);
+    git(&root, ["commit", "-m", "ADD initial readme fixture"]);
+    let backend = FakeBackend::new([
+        "patch\n@work-leaf patch update readme\n--- a/README.md\n+++ b/README.md\n@@ -1 +1 @@\n-before\n+after\n@work-leaf end\n@work-leaf done",
+        "summary: README changes",
+        "NO_FINDINGS",
+        "follow-up reply",
+    ]);
+    let chat = CommandChat::new(root, backend.clone()).with_max_review_rounds(4);
+    let mut controller = WorkLeafController::new(chat);
+
+    let agent_id = controller.create_agent("update readme").unwrap();
+    assert!(controller.wait_for_idle(Duration::from_secs(2)));
+
+    let reviewed = controller.snapshot();
+    let session = reviewed.session(&agent_id).expect("patch agent exists");
+    assert_eq!(
+        session.feature_state,
+        WorkLeafFeatureState::AwaitingDoneConfirmation
+    );
+    assert!(
+        session
+            .lines
+            .iter()
+            .any(|line| line.contains("Is this feature done? yes/no"))
+    );
+
+    let sends_before_yes = backend.sends().len();
+    controller.send_message(&agent_id, "yes").unwrap();
+
+    let closed = controller.snapshot();
+    let session = closed.session(&agent_id).expect("patch agent exists");
+    assert_eq!(session.feature_state, WorkLeafFeatureState::Done);
+    assert!(session.lines.iter().any(|line| line == "user: yes"));
+    assert!(
+        session
+            .lines
+            .iter()
+            .any(|line| line == "work-leaf: feature marked done")
+    );
+    assert_eq!(
+        backend.sends().len(),
+        sends_before_yes,
+        "yes closes the reviewed feature without sending another agent prompt"
+    );
+
+    controller
+        .send_message(&agent_id, "add follow-up work")
+        .unwrap();
+    assert!(controller.wait_for_idle(Duration::from_secs(1)));
+
+    let reopened = controller.snapshot();
+    let session = reopened.session(&agent_id).expect("patch agent exists");
+    assert_eq!(session.feature_state, WorkLeafFeatureState::Open);
+    assert!(
+        session
+            .lines
+            .iter()
+            .any(|line| line == "user: add follow-up work")
+    );
+    assert!(session.lines.iter().any(|line| line == "follow-up reply"));
+    assert!(backend.sends().iter().any(|(target, prompt)| {
+        target == &agent_id && prompt == "add follow-up work"
+    }));
+}
